  function renderGeologyHome(site, query, result, noResult) {
    return `<main id="main-content" class="fictional-site site-geology geo-page" data-fictional-site="geology" tabindex="-1">
      ${renderGeologyMasthead(site, true)}
      <div class="geo-shell">
        <aside class="geo-data-tree"><h2>File classes</h2><nav><a href="#/geology" aria-current="page">All data</a><span>Basic geology <b>4</b></span><span>Engineering survey <b>6</b></span><span>Rainfall monitoring <b>3</b></span><span>Mine-closure files <b>5</b></span><span>Slope patrol <b>2</b></span></nav><section class="geo-map-tools"><h3>Map tools</h3><div><button type="button" disabled>Pan</button><button type="button" disabled>Measure</button><button type="button" disabled>Layers</button></div><p>Enabled after a record with drawings is opened.</p></section><details class="filter-details"><summary>Data extent, coordinate, and elevation filters</summary><p>Before overlaying files from different years, check coordinate system, elevation datum, and survey extent. Similar titles are not spatial continuity.</p></details></aside>
        <section class="geo-main"><form class="geo-search-tools" data-action="site-search" data-site="geology" role="search"><div><label><span>File ID / coordinate / year</span><input type="search" name="query" value="${escapeAttr(query)}" maxlength="32" autocomplete="off" placeholder="Enter a report ID, place, or year"></label><button type="submit">Search data</button></div></form><div class="geo-facet-strip" aria-label="Catalog facets"><div><strong>File type</strong><span>Reports</span><span>Attachments</span><span>Drawings</span><span>Monitor sheets</span></div><div><strong>Date</strong><span>1990—1999</span><span>2000—2009</span><span>2020—2026</span></div><div><strong>Open status</strong><span>Catalog open</span><span>Digital attachments</span></div></div><div class="geo-result-toolbar"><div class="geo-result-summary">Search results: ${result.count}${query ? ` · query “${escapeHtml(query)}”` : ""}</div><span>Reports and attachments shown together</span></div>${noResult}${renderGeologyList(result.results)}</section>
      </div>
      <footer class="geo-site-footer"><span>NorthSlope geology library</span><span>Coordinate, elevation datum, and survey extent must be checked with the record</span><a href="#/geology">Return to data catalog</a></footer>
    </main>`;
  }

  function renderSiteHome(siteId, uiOverrides) {
    const site = SITE_BY_ID.get(siteId);
    if (!site || siteId === "workbench") return renderNotFound("This site does not exist.", "#/workbench");
    const query = uiOverrides && uiOverrides.siteQueries ? uiOverrides.siteQueries[siteId] || "" : ui.siteQueries[siteId] || "";
    const result = Core.searchRecords(siteId, query);
    const noResult = (result.kind === "miss" || result.kind === "multi" || result.kind === "invalid") && result.count === 0
      ? `<div class="site-empty"><h2>No matching records</h2><p>${escapeHtml(result.message || "Try another word from a page you already read.")}</p></div>`
      : result.kind === "empty"
        ? `<div class="site-empty"><p>${escapeHtml(result.message)}</p></div>`
        : result.kind === "forbidden"
          ? `<div class="site-empty"><h2>This file is forbidden</h2><p>${escapeHtml(result.message)}</p></div>`
          : "";
    if (siteId === "forum") return renderForumHome(site, query, result, noResult);
    if (siteId === "archive") return renderArchiveHome(site, query, result, noResult);
    if (siteId === "folk") return renderFolkHome(site, query, result, noResult);
    if (siteId === "news") return renderNewsHome(site, query, result, noResult);
    return renderGeologyHome(site, query, result, noResult);
  }

